.card__lede {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.required-legend {
  margin: 0 0 20px;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.required-marker {
  color: var(--danger);
  margin-left: 2px;
}

.optional-marker {
  color: var(--text-muted);
  font-weight: 400;
  font-size: 0.9em;
}

.contact-form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-field label {
  font-weight: 600;
  font-size: 0.92rem;
}

.form-field input {
  font: inherit;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fff;
  color: var(--text);
  transition: border-color 120ms ease, box-shadow 120ms ease;
}

.form-field input:hover {
  border-color: var(--border-strong);
}

.form-field input:focus {
  outline: 2px solid var(--focus);
  outline-offset: 1px;
  border-color: var(--focus);
}

.help-text {
  margin: 0;
  font-size: 0.82rem;
  color: var(--text-muted);
}

.form-actions {
  margin-top: 8px;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 8px;
  padding: 11px 20px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background-color 120ms ease, transform 60ms ease;
}

.btn--primary {
  background: var(--primary);
  color: #fff;
}

.btn--primary:hover {
  background: var(--primary-hover);
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(1px);
